# Let's look at conv1 filters per channel to detect corner patterns
conv1_w = W['conv1.weight']  # (16, 3, 3, 3)

print("conv1 filter spatial weights per channel:")
for i in range(16):
    print(f"\nFilter {i}:")
    for c in range(3):
        spatial = conv1_w[i, c]  # (3, 3)
        print(f"  Channel {c}:")
        for row in spatial:
            print(f"    {[f'{x:.3f}' for x in row.tolist()]}")

# Also look at filter 7 and 13 more carefully since they had uniform rows
print("\n\nFilter 7 detail (all channels):")
for c in range(3):
    print(f"  Ch {c}: {conv1_w[7, c].flatten().tolist()}")

print("\nFilter 13 detail (all channels):")
for c in range(3):
    print(f"  Ch {c}: {conv1_w[13, c].flatten().tolist()}")

print("\nFilter 14 detail (all channels):")
for c in range(3):
    print(f"  Ch {c}: {conv1_w[14, c].flatten().tolist()}")

# Look at conv3 channels 14, 50, 54 and their fc connections
