for ch in [14, 50, 54]:
    print(f"\n=== conv3 ch {ch} ===")
    for c in range(10):
        w = fc_w[c, ch].item()
        if abs(w) > 0.1:
            print(f"  fc[{c}]: {w:.3f}")

# Also look at conv3 channel 51 which has strong top edge
